import test_reduce as T

rng = random.Random(999)

# 1) Validate sat_solve vs brute force on random small CNFs
def brute_sat(inst):
    m=inst['num_vars']; cls=inst['clauses']
    for bits in itertools.product([False,True],repeat=m):
        if all(any((bits[abs(l)-1] if l>0 else not bits[abs(l)-1]) for l in c) for c in cls):
            return True
    return False

bad=0
for _ in range(3000):
    m=rng.randint(0,6)
    nc=rng.randint(0,6)
    cls=[]
    for _ in range(nc):
        k=rng.randint(0,4)
        cls.append([rng.choice([-1,1])*rng.randint(1,m) if m>0 else 0 for _ in range(k)])
    if m==0:
        cls=[[] for _ in range(nc)]
    inst={'num_vars':m,'clauses':cls}
    if T.sat_solve(inst)!=brute_sat(inst):
        bad+=1
        print('SAT SOLVER MISMATCH', inst)
print('sat_solve validation bad =', bad)

# 2) Validate subset_sum_solve vs brute force enumeration
def brute_ss(inst):
    nums=inst['numbers']; t=inst['target']
    for r in range(len(nums)+1):
        for comb in itertools.combinations(nums,r):
            if sum(comb)==t: return True
    return False
bad2=0
