    n=rng.randint(0,9)
    nums=[rng.randint(0,20) for _ in range(n)]
    t=rng.randint(-3, sum(nums)+3)
    inst={'numbers':nums,'target':t}
    if T.subset_sum_solve(inst)!=brute_ss(inst):
        bad2+=1; print('SS SOLVER MISMATCH', inst)
