# replicate the solver with tracing
def sat_solve(instance, depth=0):
    num_vars=instance['num_vars']; raw=instance['clauses']
    clauses=[]
    for c in raw:
        s=set(c)
        if any(-l in s for l in s): continue
        clauses.append(list(s))
    def propagate(clauses, assignment):
        while True:
            unit=None
            for c in clauses:
                unassigned=[]; sat=False
                for l in c:
                    v=abs(l)
                    if v in assignment:
                        if (l>0)==assignment[v]: sat=True; break
                    else: unassigned.append(l)
                if sat: continue
                if not unassigned: return False,clauses,assignment
                if len(unassigned)==1: unit=unassigned[0]; break
            if unit is None: return True,clauses,assignment
            v=abs(unit); val=unit>0
            if v in assignment:
                if assignment[v]!=val: return False,clauses,assignment
            else: assignment[v]=val
            nc=[]
            for c in clauses:
                sat=False; rem=[]
                for l in c:
                    vv=abs(l)
                    if vv in assignment:
                        if (l>0)==assignment[vv]: sat=True; break
                    else: rem.append(l)
                if not sat: nc.append(rem)
            clauses=nc
    def dpll(clauses, assignment, d=0):
        if d>50: raise Exception('deep '+str(clauses)+' '+str(assignment))
        ok,clauses,assignment=propagate(clauses,assignment)
        if not ok: return False
        if not clauses: return True
        c=min(clauses,key=len); lit=c[0]; v=abs(lit)
        for val in (True,False):
            a2=dict(assignment); a2[v]=val
            if dpll(clauses,a2,d+1): return True
        return False
    return dpll(clauses,{})
